import React, { useEffect, useMemo, useState } from "react"
import { CheckCircleIcon, SparkleIcon, XCircleIcon } from "@phosphor-icons/react"
import { DrawerShell } from "@sb-components/composites/layout/DrawerShell/DrawerShell"
import {
    AsyncContent,
    type AsyncContentEmptyProps,
    type AsyncContentErrorProps,
} from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { EnumChip } from "@sb-components/composites/chips/EnumChip/EnumChip"
import { InlineIconLabel } from "@sb-components/composites/text/InlineIconLabel/InlineIconLabel"
import { MODEL_CATEGORY_MAP, type AiModelCategory } from "@sb-components/starci/blocks/learn/SubmissionScoreCard/SubmissionScoreCard"
import { Pagination } from "@sb-components/atoms/navigation/Pagination/Pagination"

/**
 * `SubmissionAttemptsDrawer` — a presentational overlay drawer listing every
 * past graded attempt at one challenge requirement, client-paginated. A row is
 * the select action: tapping it both picks that attempt and closes the drawer.
 * Pagination is owned inside this block (the full attempt list in, sliced
 * 6-at-a-time), not a caller-controlled `currentPage`/`totalPages` pair.
 */

/** One past graded attempt at this challenge requirement. */
export interface SubmissionAttemptRecord {
    /** Stable id — the value reported to {@link SubmissionAttemptsDrawerProps.onSelect}. */
    id: string
    /** 1-based order the attempt was made in — the row turns this into "Attempt N". */
    attemptNumber: number
    /** `null` → not graded yet; the row shows an "ungraded" chip instead of a number. */
    score: number | null
    /** Denominator for `score`. `null` → the score renders bare (no "/max"). */
    maxScore: number | null
    /** Drives the verdict icon + `Chip` tone once `score` is set — pass (`success`) or fail (`danger`). */
    isPassing: boolean
    /** Already-humanized relative time (e.g. "2 hours ago"). Absent → the byline row drops the time. */
    processedTimeAgo?: string
    /** The model that graded this attempt. Absent → the byline row does not draw at all (same rule `SubmissionScoreCard` uses). */
    gradedByModel?: string
    /** Cost/quality tier of {@link gradedByModel}. */
    modelCategory?: AiModelCategory
}

/** Props for {@link SubmissionAttemptsDrawer}. */
export interface SubmissionAttemptsDrawerProps {
    /** Whether the drawer is currently open. Forwarded to `DrawerShell`. */
    isOpen: boolean
    /** Open-state change handler (backdrop click, Escape, close button, or a row selection). Forwarded to `DrawerShell`. */
    onOpenChange: (open: boolean) => void
    /** The FULL attempt history (newest first) — this block paginates it client-side, same as real `src`. */
    attempts: Array<SubmissionAttemptRecord>
    /** The attempt currently being viewed — highlighted with a trailing check. */
    selectedAttemptId?: string
    /** Fired with an attempt id when the reader taps its row. The drawer closes itself right after (same gesture as real `src`). */
    onSelect: (attemptId: string) => void
    /** `true` → this list's own fetch is in flight; the drawer shows its skeleton mirror. */
    isLoading?: boolean
    /** `true` (once loading has finished) → the drawer falls to its empty message. */
    isEmpty?: boolean
    /** Truthy → the drawer falls to its error message (beats loading, per `AsyncContent`). */
    error?: unknown
    /** Retry handler — paired with `retryLabel` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Label of the retry button — required alongside `onRetry` for it to appear. */
    retryLabel?: string
    /** Which edge the panel slides in from. Real `src` picks bottom-on-mobile itself; this port leaves that call to the caller. @default "right" */
    placement?: "top" | "bottom" | "left" | "right"
}

/** Fixed, block-owned title (§14d.1) — real `src` appends the live count, so this does too. */
const DRAWER_TITLE = "Submission history"
const EMPTY_TITLE = "No submissions yet"
const ERROR_TITLE = "Couldn't load the submission history"
const PAGER_ARIA_LABEL = "Submission history pagination"
const UNGRADED_LABEL = "Ungraded"

/** Attempts per page — same constant real `src` uses. */
const HISTORY_PAGE_SIZE = 6
/** How many skeleton rows mirror the list while `attempts` hasn't landed yet. */
const SKELETON_ATTEMPT_COUNT = 3

/** One attempt's verdict `Chip` shape — tone/icon/text, all derived from data. */
const scoreChipFor = (attempt: SubmissionAttemptRecord): { tone: "success" | "danger" | "default"; icon?: typeof CheckCircleIcon; text: string } => {
    if (attempt.score == null) {
        return { tone: "default", text: UNGRADED_LABEL }
    }
    return {
        tone: attempt.isPassing ? "success" : "danger",
        icon: attempt.isPassing ? CheckCircleIcon : XCircleIcon,
        text: attempt.maxScore != null ? `${attempt.score}/${attempt.maxScore}` : `${attempt.score}`,
    }
}

/** Turns one attempt into a {@link SurfaceCardListItem}'s free-form `content` — mirrors real `src`'s row exactly: attempt line + verdict chip + time-ago on line 1, model byline on line 2. */
const attemptRowContent = (attempt: SubmissionAttemptRecord, isSelected: boolean) => {
    const chip = scoreChipFor(attempt)

    const attemptLabelAndChip = [
        () => (
            <Typography
                text={`Attempt ${attempt.attemptNumber}`}
                size="sm"
                weight="medium"

            />
        ),
        () => <Chip tone={chip.tone} icon={chip.icon} text={chip.text} />,
    ]

    // justify="between" pushes the timeago to the far edge — the PARENT does the
    // pushing, not a child margin; the label+chip stay grouped in their own inner track
    // so `between` only ever splits two things, not three.
    const attemptLineContent = [
        () => <StackH gap={3} align="center" principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            items={attemptLabelAndChip} />,
        ...(attempt.processedTimeAgo != null ? [() => (
            <Typography
                text={attempt.processedTimeAgo}
                size="xs"
                color="muted"

            />
        )] : []),
    ]

    const bylineContent = [
        () => (
            <InlineIconLabel
                icon={SparkleIcon}
                tone="default"
                size="xs"
                label={`Graded by ${attempt.gradedByModel}`}
            />
        ),
        ...(attempt.modelCategory != null ? [() => (
            <EnumChip
                value={attempt.modelCategory ?? ""}
                map={MODEL_CATEGORY_MAP}

            />
        )] : []),
    ]

    const rowContent = [
        () => (
            <StackH
                gap={3}
                align="center"
                justify="between"
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={attemptLineContent}
            />
        ),
        ...(attempt.gradedByModel != null ? [() => (
            <StackH gap={3} align="center" at="sm" principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                items={bylineContent}  />
        )] : []),
    ]

    // highlight-exception: the selected row's tint is baked into the row's own
    // content wrapper (a plain, un-tightened `<div>`), since `SurfaceCardListItem`
    // no longer takes a raw `className` — same class real `src`'s
    // `SurfaceListCardItem` uses.
    return (
        <div className={isSelected ? "bg-accent-soft hover:bg-accent-soft" : undefined}>
            <StackV gap={2} items={rowContent} />
        </div>
    )
}

/**
 * The attempts-history drawer. See the file header for the real-`src` rebuild
 * and why selecting a row closes the drawer in the same gesture.
 *
 * @param props - {@link SubmissionAttemptsDrawerProps}
 */
const SubmissionAttemptsDrawer = ({
    isOpen,
    onOpenChange,
    attempts,
    selectedAttemptId,
    onSelect,
    isLoading = false,
    isEmpty = false,
    error,
    onRetry,
    retryLabel,
    placement = "right",
}: SubmissionAttemptsDrawerProps) => {
    const [page, setPage] = useState(1)

    // reset to the first page whenever the drawer opens — same as real `src`.
    useEffect(() => {
        if (isOpen) {
            setPage(1)
        }
    }, [isOpen])

    const totalPages = Math.max(1, Math.ceil(attempts.length / HISTORY_PAGE_SIZE))
    const pagedAttempts = useMemo(
        () => attempts.slice((page - 1) * HISTORY_PAGE_SIZE, page * HISTORY_PAGE_SIZE),
        [attempts, page],
    )

    const emptyContent: AsyncContentEmptyProps = {
        title: EMPTY_TITLE,

    }

    const errorContent: AsyncContentErrorProps = {
        title: ERROR_TITLE,
        onRetry,
        retryLabel,

    }

    const skeletonRows = Array.from({ length: SKELETON_ATTEMPT_COUNT }, () => () => (
        <div className="h-16 w-full rounded-2xl bg-default/40" />
    ))

    // `selected` (a trailing check) is only wired for the FIXED title/subtitle row
    // shape — this row uses free-form `content` instead (2 lines, richer than that
    // shape fits), so the highlight is baked into `attemptRowContent`'s own wrapper
    // div, same class real `src`'s `SurfaceListCardItem` uses.
    const items: Array<SurfaceCardListItem> = pagedAttempts.map((attempt) => ({
        key: attempt.id,
        content: () => attemptRowContent(attempt, attempt.id === selectedAttemptId),
        onPress: () => {
            onSelect(attempt.id)
            onOpenChange(false)
        },
    }))

    const listAndPager = [
        () => (
            <SurfaceCardList
                items={items}


            />
        ),
        ...(totalPages > 1 ? [() => (
            // `Pagination` hard-codes its own internal `aria-label` (§4) — the
            // wrapping `<nav>` is how this block's own accessible name still
            // gets attached, same convention `CourseQaQuestionList` uses.
            <nav aria-label={PAGER_ARIA_LABEL}>
                <Pagination
                    currentPage={page}
                    totalPages={totalPages}
                    onPageChange={setPage}

                />
            </nav>
        )] : []),
    ]

    return (
        <DrawerShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={placement}
            title={`${DRAWER_TITLE} · ${attempts.length}`}
            body={() => (
                <AsyncContent
                    isLoading={isLoading}
                    skeleton={() => (
                        <StackV
                            gap={3}
                            principle="sibling-stack"
                            explain="Skeleton attempt rows — not group-boundary, because these are peer loading placeholders."
                            items={skeletonRows}
                        />
                    )}
                    isEmpty={isEmpty}
                    emptyContent={emptyContent}
                    error={error}
                    errorContent={errorContent}
                    content={() => (
                        <StackV
                            gap={4}
                            principle="content-row"
                            explain="Attempt list over optional pager — not sibling-stack, because these are related content regions."
                            items={listAndPager}
                        />
                    )}
                />
            )}
        />
    )
}

export { SubmissionAttemptsDrawer }

"use client"

import React, { useCallback, useEffect, useState } from "react"
import { useParams } from "next/navigation"
import { useLocale, useTranslations } from "next-intl"
import { GraduationCapIcon, GithubLogoIcon } from "@phosphor-icons/react"
import { useAppSelector } from "@/redux/hooks"
import { useQueryMyGithubTeamStatusSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyGithubTeamStatusSwr"
import { useLinkGithubOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useJobNotificationsSocketIo } from "@/hooks/socketio/useJobNotificationsSocketIo"
import { PublicationEvent } from "@/hooks/socketio/enums/publication-event"
import { Callout } from "@/components/composites/feedback/Callout"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV, StackH } from "@/components/frames/Stack"
import { Cluster } from "@/components/frames/Cluster"
import { JobStatus } from "@/modules/types/enums/job-status"
import { mutateRequestToTeam } from "@/modules/api/graphql/mutations/mutation-request-to-team"

/**
 * Course GitHub-team join — NON-BLOCKING.
 *
 * A PAID-enrolled learner (the backend scopes teams to `is_enrolled = true`, so
 * trial viewers never see this) who is not yet in their course GitHub team gets a
 * persistent warning banner on the learn page (the learn page stays fully usable
 * — you just can't reach GitHub: challenges + the personal-project repo). The
 * banner opens an opt-in, DISMISSABLE modal with the step-by-step join flow:
 * link GitHub (if needed) → request to join → accept the invite on GitHub →
 * re-check. The banner clears the moment every required team flips to `active`.
 */
export const GithubTeamGate = () => {
    const t = useTranslations()
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    // current course cover for the modal identity tile (mirrors the enroll modal summary)
    const coverImageUrl = useAppSelector((state) => state.course.entity?.coverImageUrl)
    const { data, mutate, isLoading } = useQueryMyGithubTeamStatusSwr()
    const { setOpen: setLinkGithubOpen } = useLinkGithubOverlayState()
    const [requesting, setRequesting] = useState(false)
    // the guided modal is opt-in (opened from the banner CTA) and dismissable
    const [modalOpen, setModalOpen] = useState(false)
    const locale = useLocale()
    const jobNotificationsSocket = useJobNotificationsSocketIo()
    const jobStatusByJobId = useAppSelector((state) => state.socketIo.jobStatusByJobId)
    // courseId -> id of the enqueued resolve-github invite job (for realtime status)
    const [jobByCourse, setJobByCourse] = useState<Record<string, string>>({})

    // scope to the COURSE CURRENTLY BEING STUDIED (route segment [courseId] = slug).
    const params = useParams()
    const courseSlug = Array.isArray(params.courseId) ? params.courseId[0] : params.courseId
    const courseTeams = (data?.teams ?? []).filter((entry) => entry.courseSlug === courseSlug)
    const allInCourseTeams = courseTeams.every((entry) => entry.state === "active")

    // request to join THIS course's team if not invited yet (non-blocking enqueue +
    // realtime job status via socket — see the original gate's rationale).
    const onRequest = useCallback(
        async () => {
            setRequesting(true)
            try {
                const next: Record<string, string> = {}
                for (const team of courseTeams.filter((entry) => entry.state === "none")) {
                    const res = await mutateRequestToTeam({
                        request: {
                            courseId: team.courseId,
                        },
                    })
                    const jobId = res.data?.requestToTeam?.data?.jobId
                    if (jobId) {
                        next[team.courseId] = jobId
                        jobNotificationsSocket.emit(
                            PublicationEvent.SubscribeJobNotification,
                            {
                                data: {
                                    jobId,
                                },
                                locale,
                            },
                        )
                    }
                }
                setJobByCourse((prev) => ({ ...prev, ...next }))
            } finally {
                setRequesting(false)
            }
        },
        [courseTeams, jobNotificationsSocket, locale],
    )

    // when a tracked invite job settles, refetch team status once so the row flips.
    useEffect(() => {
        const settled = Object.entries(jobByCourse).filter(([, id]) => {
            const status = jobStatusByJobId[id]?.data?.status
            return status === JobStatus.Completed || status === JobStatus.Failed
        })
        if (settled.length === 0) {
            return
        }
        void mutate()
        setJobByCourse((prev) => {
            const remaining = { ...prev }
            for (const [courseId] of settled) {
                delete remaining[courseId]
            }
            return remaining
        })
    }, [jobStatusByJobId, jobByCourse, mutate])

    // show only for a viewer with a (paid) team for THIS course that isn't fully joined
    const open = Boolean(
        authenticated && data && courseTeams.length > 0 && !allInCourseTeams,
    )
    if (!open || !data) {
        return null
    }

    const linked = data.linked
    const hasUninvited = courseTeams.some((entry) => entry.state === "none")
    const anySending = Object.values(jobByCourse).some((id) => {
        const status = jobStatusByJobId[id]?.data?.status
        return status !== JobStatus.Completed && status !== JobStatus.Failed
    })

    // identity-tile state line (this course's team; gate is scoped to the current course)
    const primaryTeam = courseTeams[0]
    const primaryState = primaryTeam?.state ?? "none"
    const primaryStateLabel = anySending
        ? t("githubTeamGate.sending")
        : t(`githubTeamGate.state.${primaryState}`)
    const primaryStateTone = anySending || primaryState === "pending"
        ? "warning"
        : primaryState === "active"
            ? "success"
            : "muted"

    const linkBody = [
        () => (
            <Typography
                size="sm"
                color="muted"
                text={t("githubTeamGate.linkFirst")}
            />
        ),
        () => (
            <Button
                variant="primary"
                prefixIcon={GithubLogoIcon}
                label={t("githubTeamGate.linkCta")}
                onPress={() => {
                    // avoid stacking on the link modal it opens
                    setModalOpen(false)
                    setLinkGithubOpen(true)
                }}
            />
        ),
    ]

    const courseIdentity = [
        () => (
            <IconTile
                size="sm"
                src={coverImageUrl ?? undefined}
                icon={<GraduationCapIcon aria-hidden focusable="false" />}
            />
        ),
        () => (
            <StackV
                gap={1}
                principle="title-subtitle"
                explain="Course title over team state — not label-field, because neither line is a form control label."
                items={[
                    () => (
                        <Typography
                            size="sm"
                            weight="semibold"
                            truncate
                            text={primaryTeam?.courseTitle ?? ""}
                        />
                    ),
                    () => (
                        <Typography
                            size="xs"
                            color={primaryStateTone === "muted" ? "muted" : primaryStateTone === "warning" ? "warning" : "success"}
                            text={primaryStateLabel}
                        />
                    ),
                ]}
            />
        ),
    ]

    const stepRow = (n: number, body: React.ComponentType) => () => (
        <Cluster
            gap={3}
            principle="icon-text"
            explain="Step index beside its instruction — not name-handle, because this pairs a badge with procedural copy."
            align="start"
            items={[
                () => <Chip tone="accent" text={String(n)} />,
                body,
            ]}
        />
    )

    const joinSteps = [
        stepRow(1, () => (
            <StackV
                gap={2}
                principle="sibling-stack"
                explain="Step copy over its CTA — not group-boundary, because these are peer pieces of one step."
                items={[
                    () => <Typography size="sm" text={t("githubTeamGate.step1")} />,
                    ...(hasUninvited
                        ? [() => (
                            <Button
                                variant="primary"
                                size="sm"
                                isDisabled={requesting || anySending}
                                label={anySending
                                    ? t("githubTeamGate.sending")
                                    : t("githubTeamGate.requestCta")}
                                onPress={onRequest}
                            />
                        )]
                        : []),
                ]}
            />
        )),
        stepRow(2, () => (
            <Typography size="sm" text={t("githubTeamGate.step2")} />
        )),
        stepRow(3, () => (
            <StackV
                gap={2}
                principle="sibling-stack"
                explain="Step copy over recheck CTA — not group-boundary, because these are peer pieces of one step."
                items={[
                    () => <Typography size="sm" text={t("githubTeamGate.step3")} />,
                    () => (
                        <Button
                            variant="secondary"
                            size="sm"
                            isDisabled={isLoading}
                            label={t("githubTeamGate.recheckCta")}
                            onPress={() => mutate()}
                        />
                    ),
                ]}
            />
        )),
    ]

    const linkedBody = [
        () => (
            <StackH
                gap={3}
                principle="identity"
                explain="Keeps course tile and title/state as one peer unit so the course identity stays beside its cover."
                align="center"
                items={courseIdentity}
            />
        ),
        () => (
            <StackV
                gap={3}
                principle="sibling-stack"
                explain="Ordered join steps — not group-boundary, because these are repeating procedure rows."
                items={joinSteps}
            />
        ),
    ]

    return (
        <StackV
            gap={4}
            principle="group-boundary"
            explain="Learn-page warning banner owns the guided modal it opens — one block, two surfaces."
            identity={{ tier: "block", component: "GithubTeamGate" }}
            items={[
                () => (
                    <Callout
                        status="warning"
                        icon={GithubLogoIcon}
                        title={t("githubTeamGate.warningTitle")}
                        description={t("githubTeamGate.warningBody")}
                        actionLabel={t("githubTeamGate.openCta")}
                        onAction={() => setModalOpen(true)}
                    />
                ),
                () => (
                    <ModalShell
                        isOpen={modalOpen}
                        onOpenChange={setModalOpen}
                        title={t("githubTeamGate.title")}
                        size="sm"
                        body={() => (
                            <StackV
                                gap={4}
                                principle="content-row"
                                explain="Link prompt or join flow — not sibling-stack, because this is the modal body's content region."
                                items={linked ? linkedBody : linkBody}
                            />
                        )}
                    />
                ),
            ]}
        />
    )
}

"use client"

import React, { useEffect } from "react"
import { useTranslations } from "next-intl"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { StickyBottomBar } from "@/components/blocks/layout/StickyBottomBar"
import { useCookieConsentStore } from "@/hooks/zustand/cookieConsent/store"
import { useCookiePreferencesOverlayState } from "@/hooks/zustand/overlay/hooks"

/**
 * Cookie consent banner — the non-blocking bottom bar shown until the visitor makes a choice.
 *
 * Reads the committed consent from {@link useCookieConsentStore}; renders only while `decided === false`
 * (hidden during pre-hydration `null` and once decided `true`). Buttons keep parity (Accept / Reject are
 * equal-size real buttons — GDPR/PDPD: reject must be as easy as accept); "Customize" opens the granular
 * preferences modal. Mounted once globally in `InnerLayout`. `"use client"` for the store + i18n.
 */
export const CookieConsentBanner = () => {
    const t = useTranslations()
    const decided = useCookieConsentStore((state) => state.decided)
    const hydrate = useCookieConsentStore((state) => state.hydrate)
    const acceptAll = useCookieConsentStore((state) => state.acceptAll)
    const rejectAll = useCookieConsentStore((state) => state.rejectAll)
    const preferences = useCookiePreferencesOverlayState()

    // read the consent cookie once on mount (idempotent in the store)
    useEffect(() => {
        hydrate()
    }, [hydrate])

    // null = not hydrated yet, true = already decided → render nothing
    if (decided !== false) {
        return null
    }

    return (
        <StackV
            principle="block-boundary"
            explain="Identity host for the sticky consent chrome — StickyBottomBar owns the pin; this track only names the block."
            identity={{ tier: "block", component: "CookieConsentBanner" }}
            items={[
                () => (
                    <StickyBottomBar>
                        <StackH
                            gap={3}
                            principle="flex-action"
                            explain="Consent copy beside the Accept/Reject/Customize cluster — not sibling-stack, because the sides are asymmetric roles on one bar."
                            align="center"
                            at="sm"
                            items={[
                                () => (
                                    <Typography
                                        size="sm"
                                        color="muted"
                                        text={t("cookieConsent.body")}
                                    />
                                ),
                                () => (
                                    <StackH
                                        gap={2}
                                        principle="flex-action"
                                        explain="Equal-weight consent CTAs wrap as peers — not chip-row, because these are buttons rather than chips."
                                        align="center"
                                        at="sm"
                                        items={[
                                            () => (
                                                <Button
                                                    variant="primary"
                                                    size="sm"
                                                    label={t("cookieConsent.acceptAll")}
                                                    onPress={acceptAll}
                                                />
                                            ),
                                            () => (
                                                <Button
                                                    variant="secondary"
                                                    size="sm"
                                                    label={t("cookieConsent.reject")}
                                                    onPress={rejectAll}
                                                />
                                            ),
                                            () => (
                                                <Button
                                                    variant="tertiary"
                                                    size="sm"
                                                    label={t("cookieConsent.customize")}
                                                    onPress={preferences.open}
                                                />
                                            ),
                                        ]}
                                    />
                                ),
                            ]}
                        />
                    </StickyBottomBar>
                ),
            ]}
        />
    )
}

import React from "react"
import { WarningIcon } from "@phosphor-icons/react"
import {
    AlertDialogRoot,
    AlertDialogBackdrop,
    AlertDialogContainer,
    AlertDialogDialog,
    AlertDialogHeader,
    AlertDialogHeading,
    AlertDialogBody,
    AlertDialogFooter,
} from "@/components/atoms/feedback/AlertDialog"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { Spinner } from "@/components/atoms/display/Spinner"
import { StackH } from "@/components/frames/Stack"
import { Split } from "@/components/frames/Split"
import { resolveIdentity } from "@/components/frames/_identity"

/**
 * `MaintenanceModal` — the app-wide blocking dialog opened by the Apollo `ErrorLink`
 * when the backend keeps returning a 5xx status (persistent, not a one-off —
 * `RetryLink` already exhausted its retries before `ErrorLink` sees it). Uses the
 * house `AlertDialog*` atoms rather than the `ModalShell` composite: this dialog's
 * whole point is that it cannot be dismissed — no close button, no backdrop-click,
 * no Escape — and no composite in the design system yet exposes a non-dismissable
 * variant (`ModalShell` always renders a dismissable backdrop + close trigger).
 * It clears itself the moment a probe query succeeds; "Retry" re-probes immediately
 * without waiting for the next poll tick.
 *
 * Presentational: `isOpen`/`onOpenChange` (overlay-store wiring), `isChecking`
 * (a probe in flight), and `onRetry`. Every string arrives already translated via
 * `labels`. See `tiers/split.md` — the connected `index.tsx` owns the poll loop,
 * the probe fetch, and i18n.
 */

/** All display text, already localized by the connected `MaintenanceModal`. */
export interface MaintenanceModalLabels {
    /** Dialog heading. */
    title: string
    /** Dialog body copy. */
    description: string
    /** Status line beside the retry button, shown at rest and while a probe is in flight. */
    pollStatus: string
    /** Retry button label. */
    retry: string
}

/** Props for {@link _MaintenanceModal} — presentational; no fetch/store/i18n. */
export interface MaintenanceModalProps {
    /** Whether the dialog is currently open. */
    isOpen: boolean
    /**
     * Open-state change handler, forwarded to `AlertDialogRoot`. The dialog itself
     * blocks backdrop-click and Escape (see the file header) — this only fires
     * from within the shell's own logic.
     */
    onOpenChange: (open: boolean) => void
    /** `true` while a manual or polled probe request is in flight. */
    isChecking: boolean
    /** Fired when the retry button is pressed. */
    onRetry: () => void
    /** Every string this dialog shows, already translated. */
    labels: MaintenanceModalLabels
}

/**
 * Renders the blocking maintenance dialog. See the file header for the full contract.
 *
 * @param props - {@link MaintenanceModalProps}
 */
export const _MaintenanceModal = ({
    isOpen,
    onOpenChange,
    isChecking,
    onRetry,
    labels,
}: MaintenanceModalProps) => (
    <AlertDialogRoot
        isOpen={isOpen}
        onOpenChange={onOpenChange}
        {...resolveIdentity({ tier: "overlay", component: "MaintenanceModal" })}
    >
        <AlertDialogBackdrop
            isDismissable={false}
            isKeyboardDismissDisabled
        >
            <AlertDialogContainer size="sm">
                <AlertDialogDialog>
                    <AlertDialogHeader>
                        <WarningIcon
                            aria-hidden
                            focusable="false"
                            weight="fill"
                            className="size-5 shrink-0 text-warning"
                        />
                        <AlertDialogHeading>
                            {labels.title}
                        </AlertDialogHeading>
                    </AlertDialogHeader>
                    <AlertDialogBody>
                        <Typography text={labels.description} />
                    </AlertDialogBody>
                    <AlertDialogFooter>
                        <Split
                            gap={3}
                            principle="flex-action-between"
                            explain="Poll status on the left, retry CTA on the right — not sibling-stack, because the sides are asymmetric roles pushed apart."
                            start={() => (
                                <StackH
                                    gap={2}
                                    principle="icon-text"
                                    explain="Spinner beside its status label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                    align="center"
                                    items={[
                                        ...(isChecking ? [() => <Spinner tone="current" size="sm" />] : []),
                                        () => <Typography size="xs" color="muted" text={labels.pollStatus} />,
                                    ]}
                                />
                            )}
                            end={() => (
                                <Button
                                    variant="primary"
                                    isDisabled={isChecking}
                                    label={labels.retry}
                                    onPress={onRetry}
                                />
                            )}
                        />
                    </AlertDialogFooter>
                </AlertDialogDialog>
            </AlertDialogContainer>
        </AlertDialogBackdrop>
    </AlertDialogRoot>
)
